package store

import (
	"encoding/base64"
	"testing"
)

// Frozen disposable two-replica preparation; all signatures use public TEST
// seeds from store_test.go. No secret key, path or execution proof is included.
// Keeping the fuzz seed static avoids time/random-pair-dependent worker corpora.
const archivePruneInventoryVector = ""

func fixedArchivePruneInventory(t testing.TB) ArchivePruneInventory {
	t.Helper()
	encoded, err := base64.StdEncoding.DecodeString(archivePruneInventoryVector)
	if err != nil {
		t.Fatal(err)
	}
	inventory, err := DecodeArchivePruneInventory(encoded)
	if err != nil {
		t.Fatal(err)
	}
	return inventory
}

func TestArchivePruneInventoryGolden(t *testing.T) {
	inventory := fixedArchivePruneInventory(t)
	id, err := inventory.ID()
	if err != nil || id.String() != "e70f23ce82f121c5c8df04d35bf27e67b036b70516fa57083fd5397ae7175fc1" {
		t.Fatal("prepared inventory format changed", id, err)
	}
}
